import {ChangeDetectionStrategy, Component, inject, signal} from '@angular/core';
import {FormsModule} from '@angular/forms';
import {
  ButtonDirective,
  CodeValueService,
  MPageService,
  MpageInputComponent,
  MpageSelectComponent,
  MpageRadioComponent,
  MpageTableComponent,
  MpageIconComponent,
  IColumnConfig,
  ICodeValue
} from '@clinicaloffice/mpage-developer';

@Component({
  selector: 'app-config',
  standalone: true,
  imports: [
    FormsModule,
    ButtonDirective,
    MpageInputComponent,
    MpageSelectComponent,
    MpageRadioComponent,
    MpageTableComponent,
    MpageIconComponent
  ],
  templateUrl: './config.html',
  styleUrl: './config.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class Config {
  private mPage = inject(MPageService);
  protected codeValueService = inject(CodeValueService);

  // Section A: Code Value Browser
  codeSetNumber = '';
  codeValueResults = signal<ICodeValue[]>([]);
  codeValueColumns = signal<IColumnConfig>({
    columns: [
      {column: 'codeValue', label: 'Code Value', type: 'number', visible: true, sticky: false, width: 100, justification: 'right'},
      {column: 'display', label: 'Display', type: 'text', visible: true, sticky: false, width: 200, justification: 'left'},
      {column: 'displayKey', label: 'Display Key', type: 'text', visible: true, sticky: false, width: 200, justification: 'left'},
      {column: 'cdfMeaning', label: 'CDF Meaning', type: 'text', visible: true, sticky: false, width: 150, justification: 'left'},
      {column: 'description', label: 'Description', type: 'text', visible: true, sticky: false, width: 200, justification: 'left'}
    ],
    columnSort: []
  });

  // Section B: Personnel Lookup
  selectedPhysician = 0;
  selectedCodeValue = 0;

  // Section C: Form Controls
  textValue = '';
  numberValue = 0;
  emailValue = '';
  textareaValue = '';
  colorValue = '#3f51b5';
  dateValue = '';
  notificationPref = 'Email';

  // Section D: Button Showcase
  buttonStyles = ['default', 'raised', 'stroked', 'icon'];
  buttonColors = ['default', 'primary', 'accent', 'warn'];

  lookupCodeSet(): void {
    const codeSet = parseInt(this.codeSetNumber, 10);
    if (!codeSet || isNaN(codeSet)) {
      this.mPage.notifyUser('Please enter a valid code set number', 3000, 'bottom', '20em', 'warn');
      return;
    }
    this.codeValueService.load(codeSet, undefined, undefined, undefined, undefined, true, () => {
      const results = this.codeValueService.getCodeSet(codeSet);
      this.codeValueResults.set(results);
      if (results.length === 0) {
        this.mPage.notifyUser('No code values found for code set ' + codeSet, 3000, 'bottom', '20em', 'warn');
      } else {
        this.mPage.notifyUser('Loaded ' + results.length + ' code values', 2000, 'bottom', '20em', 'primary');
      }
    });
  }

  notify(position: string, color: string, delay: number): void {
    this.mPage.notifyUser('Notification from ' + position + ' (' + color + ')', delay, position, '20em', color);
  }

  getButtonIcon(style: string): string {
    if (style === 'icon') {
      return 'star';
    }
    return '';
  }
}
